// @ts-check
/**
 * `apps/site/public/agent-manifest.json` is generated by `scripts/build-agent-manifest.mjs` from the
 * Arc deployment record, the Arc config and VaultCore.sol. Four things are pinned here:
 *
 *   1. DRIFT. The committed file equals the generator's output byte for byte. Edit one address in
 *      the JSON, or change the record without regenerating, and this goes red.
 *   2. DERIVATION. Every address and number the manifest carries equals the field of the deployment
 *      record it claims to come from, and every address-shaped string in it exists in the record.
 *   3. THE FUNCTION TABLE IS READ AGAINST THE SOLIDITY. Each row names a function that exists in the
 *      named contract with the stated parameter count, a row tagged `anyone` carries no
 *      `msg.sender ==` requirement in its body, and a gated row carries the revert the source has.
 *      The checker is itself probed on fixtures, so a checker that stops checking goes red.
 *   4. POINTERS. Both `llms.txt` copies point at the manifest and name a file that exists.
 *
 * The prose in the manifest is walked by `claims-lede-truth` (it takes every `.json`), so wording
 * here is covered there, not restated.
 *
 * MUTATION PROBES, run by hand and recorded in the PR: change one address in the committed JSON
 * (drift and derivation red); change one `whoMayCall` gate in the generator's table to a function
 * that does not exist (table red); delete the `OnlyGovernance` revert from a fixture (checker probe
 * red); edit one line of one `llms.txt` copy (token-absence red).
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildManifest, observationWindowFromSource, FUNCTION_TABLE } from '../lib/agent-manifest.mjs';
import { parseSolidityFns } from '../lib/claims-shapes.mjs';
import { generate, MANIFEST_PATH } from '../build-agent-manifest.mjs';

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const read = (rel) => readFileSync(path.join(REPO, rel), 'utf8');
const readJson = (rel) => JSON.parse(read(rel));

const record = readJson('contracts/config/deployments/arc-mainnet.json');
const config = readJson('contracts/config/arc-mainnet.json');
const committed = read(MANIFEST_PATH);
const manifest = JSON.parse(committed);
const ADDRESS = /^0x[0-9a-fA-F]{40}$/;

test('the committed manifest equals the generator output byte for byte', () => {
  assert.equal(
    committed,
    generate(),
    'apps/site/public/agent-manifest.json is stale or hand-edited. Run `node scripts/build-agent-manifest.mjs` and commit the result.',
  );
});

test('every address-shaped string in the manifest exists in the deployment record', () => {
  const inRecord = new Set();
  (function walk(v) {
    if (typeof v === 'string') {
      for (const m of v.matchAll(/0x[0-9a-fA-F]{40}\b/g)) inRecord.add(m[0].toLowerCase());
    } else if (v && typeof v === 'object') Object.values(v).forEach(walk);
  })(record);
  const found = [];
  (function walk(v) {
    if (typeof v === 'string' && ADDRESS.test(v)) found.push(v);
    else if (v && typeof v === 'object') Object.values(v).forEach(walk);
  })(manifest);
  assert.ok(found.length >= 12, `expected at least 12 addresses in the manifest, found ${found.length}`);
  const unknown = found.filter((a) => !inRecord.has(a.toLowerCase()));
  assert.deepEqual(unknown, [], 'these manifest addresses are not in contracts/config/deployments/arc-mainnet.json');
});

test('each manifest field equals the record field it is derived from', () => {
  const pairs = [
    [manifest.chain.chainId, record.chainId],
    [manifest.chain.rpc, record.rpc],
    [manifest.chain.rpcCrossCheck, record.crossCheckedOn],
    [manifest.chain.explorer, record.explorer],
    [manifest.contracts.VaultFactory, record.singletons.VaultFactory],
    [manifest.contracts.Governance, record.singletons.Governance],
    [manifest.contracts.OperatorRegistry, record.singletons.OperatorRegistry],
    [manifest.contracts.FeeEngine, record.singletons.FeeEngine],
    [manifest.contracts.SubVaultRegistry, record.singletons.SubVaultRegistry],
    [manifest.contracts.VaultDeployer, record.singletons.VaultDeployer],
    [manifest.contracts.ChainlinkOracle, record.oracle.ChainlinkOracle],
    [manifest.contracts.AggregationRouterAdapter, record.execution.AggregationRouterAdapter],
    [manifest.tokens.USDC, record.infrastructure.usdc],
    [manifest.tokens.cirBTC, record.oracle.assets.cirBTC.token],
    [manifest.firstVault.address, record.firstVault.address],
    [manifest.firstVault.address, record.verifiedWiring['factory.allVaults(0)']],
    [manifest.firstVault.creator, record.firstVault.creator],
    [manifest.firstVault.timingSeconds.commitDuration, record.firstVault.configOf.commitDuration],
    [manifest.firstVault.timingSeconds.revealDuration, record.firstVault.configOf.revealDuration],
    [manifest.firstVault.timingSeconds.timelockDuration, record.firstVault.configOf.timelockDuration],
    [manifest.firstVault.timingSeconds.executionWindow, record.firstVault.configOf.executionWindow],
    [manifest.firstVault.timingSeconds.proposalCooldown, record.firstVault.configOf.proposalCooldown],
    [manifest.firstVault.minDepositUsdc, config.smoke.minDepositUsdc],
    [manifest.firstVault.capacityCapUsdc, config.smoke.capacityCapUsdc],
  ];
  pairs.forEach(([got, want], i) => assert.equal(got, want, `pair ${i}: manifest ${got} !== source ${want}`));
  assert.equal(manifest.chain.chainId, 5042);
  assert.notEqual(manifest.chain.rpc, manifest.chain.rpcCrossCheck, 'the two RPC endpoints must differ');
});

test('the observation window equals the VaultCore constant, and the parser throws when the constant moves', () => {
  const src = read('contracts/src/VaultCore.sol');
  assert.equal(manifest.firstVault.observationWindowSeconds, observationWindowFromSource(src));
  assert.equal(observationWindowFromSource(src), 4 * 3600);
  assert.throws(() => observationWindowFromSource('uint256 public constant OTHER = 4 hours;'), /OBSERVATION_WINDOW/);
});

test('the builder throws on a missing source field instead of writing a hole', () => {
  const mutated = structuredClone(record);
  delete mutated.singletons.Governance;
  assert.throws(
    () => buildManifest({ record: mutated, config, observationWindowSeconds: 14400 }),
    /singletons\.Governance/,
  );
  const moved = structuredClone(record);
  moved.singletons.Governance = '0x0000000000000000000000000000000000000001';
  assert.notEqual(
    JSON.stringify(buildManifest({ record: moved, config, observationWindowSeconds: 14400 })),
    JSON.stringify(manifest),
    'changing the record must change the manifest',
  );
});

// ---------------------------------------------------------------------------------------------
// The function table, read against the Solidity.
// ---------------------------------------------------------------------------------------------

/** Count top-level parameters in a Solidity parameter list. */
const paramCount = (list) => {
  const t = list.trim();
  if (t === '') return 0;
  let depth = 0;
  let n = 1;
  for (const ch of t) {
    if (ch === '(' || ch === '[') depth++;
    else if (ch === ')' || ch === ']') depth--;
    else if (ch === ',' && depth === 0) n++;
  }
  return n;
};

/** What each non-`anyone` gate must look like in the function body. */
const GATE_EVIDENCE = {
  OnlyFactory: /require\([^;]*OnlyFactory\(\)/,
  OnlyAttestedVault: /require\([^;]*OnlyAttestedVault\(\)/,
  OnlyGovernance: /require\([^;]*OnlyGovernance\(\)/,
  NotVaultCreator: /require\([^;]*NotVaultCreator\(\)/,
  'reverts SubVaultsDisabled': /require\([^;]*SubVaultsDisabled\(\)/,
  stake: /NoWeight\(\)/,
  committer: /commitOf\[pid\]\[msg\.sender\]/,
};

/**
 * Problems with one table row against one contract's source. Pure, so the probes below can feed it
 * fixtures. Returns an array of strings, empty when the row is true to the source.
 * @param {{contract: string, function: string, gate: string}} row
 * @param {string} src
 */
export const rowProblems = (row, src) => {
  const name = row.function.slice(0, row.function.indexOf('('));
  const rowParams = row.function.slice(row.function.indexOf('(') + 1, row.function.lastIndexOf(')'));
  const want = paramCount(rowParams);
  const problems = [];
  const fns = parseSolidityFns(src).filter((f) => f.name === name);
  const publicGetter = new RegExp(`\\bpublic\\s+${name}\\b`).test(src);
  if (fns.length === 0) {
    if (!publicGetter) problems.push(`${row.contract}.${name} does not exist in the source`);
    return problems;
  }
  // Arity: find every `function name(` in the source and compare counts.
  const sigs = [...src.matchAll(new RegExp(`function\\s+${name}\\s*\\(([^)]*)\\)`, 'g'))].map((m) => paramCount(m[1]));
  if (!sigs.includes(want)) problems.push(`${row.contract}.${name} has no overload with ${want} parameter(s); source has ${sigs.join(', ')}`);
  const bodies = fns.map((f) => f.body);
  if (row.gate === 'anyone') {
    if (bodies.some((b) => /msg\.sender\s*[!=]=/.test(b))) problems.push(`${row.contract}.${name} is tagged anyone but its body compares msg.sender`);
  } else {
    const evidence = GATE_EVIDENCE[row.gate];
    if (!evidence) problems.push(`${row.contract}.${name}: unknown gate tag "${row.gate}"`);
    else if (!bodies.some((b) => evidence.test(b))) problems.push(`${row.contract}.${name}: gate "${row.gate}" has no matching requirement in the source`);
  }
  return problems;
};

test('every function-table row is true to the Solidity it names', () => {
  assert.ok(FUNCTION_TABLE.length >= 25, 'the table must not shrink silently');
  const problems = [];
  for (const row of FUNCTION_TABLE) {
    const file = `contracts/src/${row.contract}.sol`;
    assert.ok(existsSync(path.join(REPO, file)), `${file} does not exist`);
    problems.push(...rowProblems(row, read(file)));
  }
  assert.deepEqual(problems, []);
});

test('the manifest table is the generator table, row for row', () => {
  assert.deepEqual(
    manifest.functions.map((f) => `${f.contract}.${f.function}`),
    FUNCTION_TABLE.map((f) => `${f.contract}.${f.function}`),
  );
});

test('createChildVault is listed as unavailable because the record says the factory forbids sub-vaults', () => {
  assert.equal(record.verifiedWiring['factory.allowSubVaults()'], false);
  const row = manifest.functions.find((f) => f.function.startsWith('createChildVault'));
  assert.match(row.whoMayCall, /Not callable/);
});

test('probe: the row checker reddens on a missing function, a wrong arity, a lost gate and a false anyone', () => {
  const src = `
    contract C {
      function open(uint256 a) external { x = a; }
      function guarded(uint256 a, uint256 b) external { require(msg.sender == address(governance), OnlyGovernance()); }
      function sneaky(uint256 a) external { require(msg.sender == owner, NotOwner()); }
    }`;
  const ok = (row) => rowProblems({ contract: 'C', ...row }, src);
  assert.deepEqual(ok({ function: 'open(uint256)', gate: 'anyone' }), []);
  assert.deepEqual(ok({ function: 'guarded(uint256,uint256)', gate: 'OnlyGovernance' }), []);
  assert.notDeepEqual(ok({ function: 'missing(uint256)', gate: 'anyone' }), [], 'a function that does not exist');
  assert.notDeepEqual(ok({ function: 'open(uint256,uint256)', gate: 'anyone' }), [], 'wrong arity');
  assert.notDeepEqual(ok({ function: 'open(uint256)', gate: 'OnlyGovernance' }), [], 'a gate the body does not have');
  assert.notDeepEqual(ok({ function: 'sneaky(uint256)', gate: 'anyone' }), [], 'tagged anyone but gated');
  assert.notDeepEqual(ok({ function: 'guarded(uint256,uint256)', gate: 'nonsense' }), [], 'unknown tag');
});

// ---------------------------------------------------------------------------------------------
// Pointers and shape.
// ---------------------------------------------------------------------------------------------

test('both llms.txt copies point at the manifest, and the pointer names a file that exists', () => {
  for (const f of ['llms.txt', 'apps/site/public/llms.txt']) {
    const text = read(f);
    const m = /\[Agent manifest\]\(([^)]+)\)/.exec(text);
    assert.ok(m, `${f} has no [Agent manifest](...) pointer`);
    assert.equal(m[1], MANIFEST_PATH);
    assert.ok(existsSync(path.join(REPO, m[1])), `${f} points at ${m[1]}, which does not exist`);
  }
  assert.equal(read('llms.txt'), read('apps/site/public/llms.txt'), 'the two llms.txt copies must be byte-identical');
});

test('the manifest carries the untrusted-input rule, the ABI path, the seeded-address pointer and the launch caveats', () => {
  assert.match(manifest.trust, /untrusted input/);
  assert.match(manifest.trust, /eth_getCode/);
  assert.match(manifest.abis.path, /^contracts\/out\//);
  assert.ok(existsSync(path.join(REPO, manifest.seededAddresses.path)), 'docs/seeded-addresses.json must exist');
  assert.match(manifest.otherVaults, /vaultCount\(\)/);
  assert.match(manifest.otherVaults, /allVaults\(i\)/);
  const status = manifest.launchStatus.join(' ');
  for (const needle of ['2026-09-23', 'v0.4.0-audit', 'below five members', 'LAUNCH-READINESS']) {
    assert.ok(status.includes(needle), `launchStatus must mention ${needle}`);
  }
  assert.match(manifest.functionsNote, /Operatorship confers no authority to vote, execute, pause, reprice, or move member funds\./);
});
